/**
 * 把 infos.json 按谱师拆成分组数据（原来是 python/getCharter.py 干这件事）。
 *
 * 结构：「谱师 → 曲目键名 → { name, EZ: { lvl, charter, tcharter }, … }」，
 * 谱师按名字排序、每个谱师下的曲目按曲名排序 —— 和原先预生成的 charters.json 完全一致。
 * 这里只做纯计算，不碰网络，方便单独验证与复用。
 */

/** 参与分组的难度；顺序决定同一首歌里难度键的先后 */
export const CHARTER_DIFFICULTIES = ['EZ', 'HD', 'IN', 'AT', 'LY', 'SP']

const text = value => (value === undefined || value === null ? '' : String(value).trim())

/** 码点比较，等价于 Python 的 sorted()（曲名可能夹中文，不按语言环境排） */
const compare = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function groupByCharter(songData) {
  const grouped = {}
  for (const [songKey, songInfo] of Object.entries(songData || {})) {
    const songName = songInfo?.name || ''
    for (const diff of CHARTER_DIFFICULTIES) {
      const diffData = songInfo?.[diff]
      if (!diffData || typeof diffData !== 'object') continue
      const tcharter = text(diffData.tcharter)
      if (!tcharter) continue
      const charter = text(diffData.charter)
      const lvl = text(diffData.lvl)
      // 多人合作谱面写成「A & B」，每个人都要单独出现在列表里
      for (const charterName of tcharter.split('&').map(text).filter(Boolean)) {
        if (!grouped[charterName]) grouped[charterName] = {}
        const songs = grouped[charterName]
        if (!songs[songKey]) songs[songKey] = { name: songName }
        songs[songKey][diff] = { lvl, charter, tcharter }
      }
    }
  }

  const sorted = {}
  for (const charterName of Object.keys(grouped).sort(compare)) {
    sorted[charterName] = Object.fromEntries(
      Object.entries(grouped[charterName]).sort((a, b) => compare(a[1].name, b[1].name))
    )
  }
  return sorted
}
